-- 销售订单明细表
-- 时间跨度: 2024-01-01 ~ 2025-12-31, 25,606 条订单
-- 导入方式: mysql -u用户名 -p 数据库名 < sales_orders_mysql.sql

DROP TABLE IF EXISTS `sales_orders`;

CREATE TABLE `sales_orders` (
  `order_id` INT NOT NULL,
  `order_date` DATE NOT NULL,
  `region` VARCHAR(20) NOT NULL,
  `city` VARCHAR(20) NOT NULL,
  `product_category` VARCHAR(30) NOT NULL,
  `sku` VARCHAR(30) NOT NULL,
  `sales_rep` VARCHAR(20) NOT NULL,
  `channel` VARCHAR(10) NOT NULL,
  `customer_type` VARCHAR(10) NOT NULL,
  `quantity` INT NOT NULL,
  `unit_price` DECIMAL(10,2) NOT NULL,
  `discount_rate` DECIMAL(5,3) NOT NULL,
  `revenue` DECIMAL(12,2) NOT NULL,
  `cost` DECIMAL(12,2) NOT NULL,
  `profit` DECIMAL(12,2) NOT NULL,
  PRIMARY KEY (`order_id`),
  KEY `idx_order_date` (`order_date`),
  KEY `idx_region` (`region`),
  KEY `idx_category` (`product_category`),
  KEY `idx_sales_rep` (`sales_rep`),
  KEY `idx_channel` (`channel`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;





















































